public class AppearanceSettingsActivity extends Activity {
    static final int PICK_WALLPAPER=701;
    SharedPreferences prefs; LinearLayout box; int section;
    android.view.View focusRoot;
    final String[] titles={"Général","Apparence","Rangées de l’accueil","Cartes et icônes","Fond d’écran","Sauvegarde et réinitialisation"};
    @Override public void onCreate(Bundle b){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);configureDrawer();prefs=getSharedPreferences(HaClient.PREFS,MODE_PRIVATE);section=getIntent().getIntExtra("section",0);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.HORIZONTAL);root.setBackgroundColor(Color.rgb(31,36,45));LinearLayout left=new LinearLayout(this);left.setOrientation(LinearLayout.VERTICAL);left.setPadding(dp(82),dp(54),dp(45),dp(44));root.addView(left,new LinearLayout.LayoutParams(0,-1,.46f));TextView main=text("Paramètres",30,Color.rgb(242,243,245),false);main.setPadding(0,0,0,dp(32));left.addView(main);TextView group=text("PARAMÈTRES DU LAUNCHER",10,Color.rgb(169,173,181),true);group.setPadding(0,0,0,dp(10));left.addView(group);TextView selected=text(titles[Math.max(0,Math.min(section,titles.length-1))],15,Color.rgb(22,25,30),false);selected.setGravity(Gravity.CENTER_VERTICAL);selected.setPadding(dp(24),0,dp(18),0);selected.setBackground(round(Color.rgb(239,241,244),14));TvFocus.sectionMarker(selected);left.addView(selected,new LinearLayout.LayoutParams(-1,dp(56)));ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Color.rgb(31,36,45));box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(55),dp(54),dp(72),dp(38));scroll.addView(box);root.addView(scroll,new LinearLayout.LayoutParams(0,-1,.54f));box.addView(text(titles[Math.max(0,Math.min(section,titles.length-1))],30,Color.WHITE,false));TextView help=text(description(),14,Color.rgb(166,171,180),false);help.setPadding(0,dp(7),0,dp(17));box.addView(help);buildSection();Button back=button("Terminer",true);back.setOnClickListener(v->finish());box.addView(back);TvFocus.prepare(root);focusRoot=root;setContentView(root);TvFocus.restoreFocus(root,b==null?0:b.getInt("focus_index",0));}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(focusRoot!=null)out.putInt("focus_index",TvFocus.focusedIndex(focusRoot));}
    void configureDrawer(){getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);}
    String description(){switch(section){case 0:return"Comportement du launcher, informations affichées et applications Android.";case 1:return"Ajustez la densité et la présence visuelle de l’écran d’accueil.";case 2:return"Choisissez les rangées visibles, comme dans Projectivy.";case 3:return"Forme des icônes dans les favoris et les applications, taille et espacement des cartes.";case 4:return"Choisissez l’ambiance du fond sans afficher de contenu fictif.";default:return"Conservez une copie locale de la mise en page ou revenez aux réglages d’origine.";}}
    void buildSection(){if(section==1){Button layout=button("Disposition, barre fixe, tailles et couleurs",false);layout.setOnClickListener(v->startActivity(new Intent(this,LayoutSettingsActivity.class)));box.addView(layout);}switch(section){
        case 0:heading("DÉMARRAGE");toggle("Ouvrir directement les applications","start_apps",false,"Affiche l’onglet Applications au démarrage");heading("BARRE SUPÉRIEURE");toggle("Afficher l’heure","show_clock",true,"Horloge dans la barre");slider("Taille de l’heure",14,40,"nav_clock_size",20,"");slider("Taille de l’état de connexion",10,28,"nav_status_size",14,"");toggle("Afficher l’état Home Assistant","show_status",true,"Indique si la maison est connectée");heading("APPLICATIONS");toggle("Inclure les applications non-TV","show_mobile_apps",true,"Affiche aussi les applications Android classiques");break;
        case 1:heading("HERO");toggle("Afficher la salutation","show_greeting",true,"Bonne matinée, bon après-midi ou bonsoir");slider("Taille de la salutation",44,78,"greeting_size",64,"");toggle("Afficher le texte d’ambiance","show_subtitle",true,"Phrase sous la salutation");textField("Texte d’ambiance","hero_subtitle","Votre salon, simplement.");slider("Taille du texte d’ambiance",14,30,"subtitle_size",22,"");slider("Assombrissement du fond",0,75,"background_dim",8,"%");break;
        case 2:heading("CONTENU");toggle("Favoris","show_favorites",true,"Rangée d’applications choisies");toggle("Reprendre la lecture","show_continue",true,"N’apparaît que si un contenu réel est disponible");toggle("Votre maison","show_home",true,"Appareils et fonctions Home Assistant");Button home=button("Configurer la rangée Votre maison",false);home.setOnClickListener(v->startActivity(new android.content.Intent(this,HomeRowSettingsActivity.class)));box.addView(home);break;
        case 3:heading("FORME DES ICÔNES");iconShapeChoice("Ronde",AppIconRenderer.ROUND);iconShapeChoice("Carrée arrondie",AppIconRenderer.ROUNDED_SQUARE);iconShapeChoice("Carrée",AppIconRenderer.SQUARE);iconShapeChoice("Cookie à 4 côtés",AppIconRenderer.COOKIE_FOUR);iconShapeChoice("Cookie à 7 côtés",AppIconRenderer.COOKIE_SEVEN);iconShapeChoice("Arche",AppIconRenderer.ARCH);heading("FAVORIS");slider("Taille des favoris",44,72,"favorite_icon_size",59,"");slider("Espacement des favoris",130,220,"favorite_cell_width",184,"");toggle("Afficher les noms","show_app_labels",true,"Libellé sous chaque application");heading("CARTES HOME ASSISTANT");slider("Hauteur des cartes",90,120,"home_card_height",108,"");slider("Opacité des cartes",35,100,"home_card_opacity",90,"%");heading("FOCUS ET CARTES");slider("Coins arrondis",4,30,"card_roundness",18,"");slider("Épaisseur du focus",2,6,"focus_width",4,"");break;
        case 4:heading("SOURCE");wallpaperButton("Salon zen","Photo intégrée",0);wallpaperButton("Dégradé bleu-noir","Fond calme sans image",1);wallpaperButton("Noir minimal","Fond uni très discret",2);Button solid=button((prefs.getInt("wallpaper_mode",0)==WallpaperBackdrop.SOLID?"✓  ":"")+"Couleur unie · Choisir une couleur",false);solid.setOnClickListener(v->startActivityForResult(new Intent(this,WallpaperColorActivity.class),702));box.addView(solid);Button album=button((prefs.getInt("wallpaper_mode",0)==4?"✓  ":"")+"Google Photos · Diaporama synchronisé",false);album.setOnClickListener(v->startActivity(new Intent(this,AlbumWallpaperActivity.class)));box.addView(album);Button custom=button((prefs.getInt("wallpaper_mode",0)==3?"✓  ":"")+"+  Ajouter une image personnelle",false);custom.setOnClickListener(v->pickWallpaper());box.addView(custom);String uri=prefs.getString("custom_wallpaper_uri","");if(!uri.isEmpty()){TextView current=text("Image personnelle enregistrée",12,Color.rgb(166,171,180),false);current.setPadding(dp(8),0,0,dp(8));box.addView(current);Button remove=button("Retirer l’image personnelle",false);remove.setOnClickListener(v->{prefs.edit().remove("custom_wallpaper_uri").putInt("wallpaper_mode",0).apply();recreate();});box.addView(remove);}heading("AFFICHAGE DE L’IMAGE");choice("Recadrer et remplir",0,"wallpaper_fit");choice("Ajuster sans couper",1,"wallpaper_fit");choice("Étirer à l’écran",2,"wallpaper_fit");slider("Position horizontale",0,100,"wallpaper_focus_x",50,"%");slider("Position verticale",0,100,"wallpaper_focus_y",50,"%");heading("LISIBILITÉ");slider("Dégradé à gauche",0,100,"wallpaper_left_overlay",100,"%");slider("Largeur du dégradé",35,100,"wallpaper_overlay_width",82,"%");slider("Dégradé en bas",0,100,"wallpaper_bottom_overlay",100,"%");slider("Assombrissement général",0,75,"background_dim",8,"%");break;
        default:heading("SAUVEGARDE LOCALE");Button save=button("Créer une sauvegarde",false);save.setOnClickListener(v->backup());box.addView(save);Button restore=button("Restaurer la sauvegarde",false);restore.setOnClickListener(v->restore());box.addView(restore);heading("RÉINITIALISER");Button reset=button("Rétablir les réglages du launcher",false);reset.setOnClickListener(v->confirmReset());box.addView(reset);break;
    }}
    void heading(String s){TextView h=text(s,11,Color.rgb(255,199,93),true);h.setPadding(dp(4),dp(12),0,dp(6));box.addView(h);}
    void toggle(String title,String key,boolean def,String sub){LinearLayout card=card();LinearLayout labels=new LinearLayout(this);labels.setOrientation(LinearLayout.VERTICAL);labels.addView(text(title,15,Color.WHITE,true));labels.addView(text(sub,11,Color.rgb(155,160,169),false));card.addView(labels,new LinearLayout.LayoutParams(0,-2,1));Switch s=new Switch(this);s.setChecked(prefs.getBoolean(key,def));s.setFocusable(true);s.setThumbTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{Color.rgb(255,199,93),Color.GRAY}));s.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean(key,on).apply());card.addView(s);box.addView(card);}
    void slider(String title,int min,int max,String key,int def,String suffix){LinearLayout card=card();card.setOrientation(LinearLayout.VERTICAL);TextView label=text(title+"  ·  "+prefs.getInt(key,def)+suffix,14,Color.WHITE,true);card.addView(label);SeekBar s=new SeekBar(this);s.setMin(min);s.setMax(max);s.setProgress(prefs.getInt(key,def));s.setFocusable(true);s.setProgressTintList(ColorStateList.valueOf(Color.rgb(255,199,93)));s.setThumbTintList(ColorStateList.valueOf(Color.rgb(255,199,93)));s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean f){label.setText(title+"  ·  "+v+suffix);prefs.edit().putInt(key,v).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});card.addView(s,new LinearLayout.LayoutParams(-1,dp(34)));box.addView(card);}
    void textField(String label,String key,String def){heading(label.toUpperCase(java.util.Locale.FRANCE));EditText e=new EditText(this);e.setSingleLine(true);e.setText(prefs.getString(key,def));e.setTextSize(15);e.setTextColor(Color.WHITE);e.setPadding(dp(18),0,dp(18),0);e.setBackground(round(Color.rgb(25,30,38),14));e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){prefs.edit().putString(key,s.toString()).apply();}public void afterTextChanged(Editable e){}});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(50));lp.bottomMargin=dp(7);box.addView(e,lp);}
    void wallpaperButton(String title,String sub,int mode){Button b=button((prefs.getInt("wallpaper_mode",0)==mode?"✓  ":"")+title+"\n"+sub,false);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setOnClickListener(v->{prefs.edit().putInt("wallpaper_mode",mode).apply();recreate();});box.addView(b);}
    void choice(String title,int value,String key){Button b=button((prefs.getInt(key,0)==value?"✓  ":"")+title,false);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setOnClickListener(v->{prefs.edit().putInt(key,value).apply();recreate();});box.addView(b);}
    void iconShapeChoice(String title,int shape){
        boolean selected=prefs.getInt("app_icon_shape",AppIconRenderer.ROUND)==shape;
        Button b=button((selected?"✓  ":"")+title,false);
        b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);
        android.graphics.drawable.Drawable preview=AppIconShape.preview(shape,0xff66b5cc);
        preview.setBounds(0,0,dp(28),dp(28));
        b.setCompoundDrawables(preview,null,null,null);b.setCompoundDrawablePadding(dp(16));
        b.setContentDescription(title+(selected?", forme actuelle":""));
        b.setOnClickListener(v->{prefs.edit().putInt("app_icon_shape",shape).apply();recreate();});
        box.addView(b);
    }
    void pickWallpaper(){Intent i=new Intent("android.provider.action.PICK_IMAGES");i.setType("image/*");if(i.resolveActivity(getPackageManager())==null){i=new Intent(Intent.ACTION_GET_CONTENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");}startActivityForResult(i,PICK_WALLPAPER);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==702){if(result==RESULT_OK)recreate();return;}if(request!=PICK_WALLPAPER||result!=RESULT_OK||data==null||data.getData()==null)return;Uri source=data.getData();File target=new File(getFilesDir(),"custom_wallpaper");try(InputStream in=getContentResolver().openInputStream(source);FileOutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))>0)out.write(buffer,0,n);prefs.edit().putString("custom_wallpaper_uri",Uri.fromFile(target).toString()).putInt("wallpaper_mode",3).apply();recreate();}catch(Exception e){Toast.makeText(this,"Impossible de copier cette image",Toast.LENGTH_LONG).show();}}
    LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);l.setPadding(dp(18),dp(9),dp(16),dp(9));l.setBackground(round(Color.rgb(25,30,38),14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(6);l.setLayoutParams(lp);return l;}
    TextView text(String s,int z,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(color);t.setTypeface(bold?android.graphics.Typeface.DEFAULT_BOLD:android.graphics.Typeface.DEFAULT);t.setPadding(0,dp(3),0,dp(3));return t;}
    Button button(String s,boolean accent){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setTextColor(accent?Color.rgb(18,20,24):Color.WHITE);b.setAllCaps(false);StateListDrawable states=new StateListDrawable();states.addState(new int[]{android.R.attr.state_focused},round(Color.rgb(241,243,246),14));states.addState(new int[]{},round(accent?Color.rgb(255,199,93):Color.rgb(27,32,40),14));b.setBackground(states);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(s.contains("\n")?62:48));lp.bottomMargin=dp(7);b.setLayoutParams(lp);return b;}
    GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    String[] legacyKeys(){return new String[]{"start_apps","show_clock","show_status","show_mobile_apps","show_greeting","greeting_size","show_subtitle","hero_subtitle","subtitle_size","background_dim","show_favorites","show_continue","show_home","home_row_title","home_columns","home_show_states","home_source_ha","home_group_entity","dashboard_entities_order","favorite_icon_size","favorite_cell_width","app_icon_shape","home_card_height","home_card_opacity","icon_radius","app_gap","show_app_labels","card_roundness","focus_width","wallpaper_mode","photo_album_url","photo_album_seconds","photo_album_fade_ms","photo_album_shuffle","photo_album_sync_minutes","photo_album_cache_mb","custom_wallpaper_uri","wallpaper_fit","wallpaper_focus_x","wallpaper_focus_y","wallpaper_left_overlay","wallpaper_overlay_width","wallpaper_bottom_overlay","favorite_apps_order","custom_cards_yaml","custom_cards_previous","cards_remote_url","cards_remote_enabled","cards_remote_cache","dashboard_columns","dashboard_include_entities","start_dashboard"};}
    String[] keys(){java.util.Set<String> all=new java.util.LinkedHashSet<>(java.util.Arrays.asList(legacyKeys()));java.util.Iterator<String> it=PanelStore.schema(this).keys();while(it.hasNext())all.add(it.next());return all.toArray(new String[0]);}
    void backup(){try{JSONObject o=new JSONObject();for(String k:keys()){Object v=prefs.getAll().get(k);if(v!=null)o.put(k,v);}prefs.edit().putString("launcher_backup",o.toString()).apply();Toast.makeText(this,"Mise en page sauvegardée",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Sauvegarde impossible",Toast.LENGTH_SHORT).show();}}
    void restore(){String raw=prefs.getString("launcher_backup","");if(raw.isEmpty()){Toast.makeText(this,"Aucune sauvegarde locale",Toast.LENGTH_SHORT).show();return;}try{JSONObject o=new JSONObject(raw);SharedPreferences.Editor e=prefs.edit();for(String k:keys())if(o.has(k)){Object v=o.get(k);if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else e.putString(k,String.valueOf(v));}e.apply();Toast.makeText(this,"Mise en page restaurée",Toast.LENGTH_SHORT).show();}catch(Exception ex){Toast.makeText(this,"Sauvegarde invalide",Toast.LENGTH_SHORT).show();}}
    void confirmReset(){AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Réinitialiser le launcher ?").setMessage("La connexion Home Assistant sera conservée.").setNegativeButton("Annuler",null).setPositiveButton("Réinitialiser",(d,w)->{SharedPreferences.Editor e=prefs.edit();for(String k:keys())e.remove(k);e.apply();Toast.makeText(this,"Réglages réinitialisés",Toast.LENGTH_SHORT).show();finish();}).create();dialog.setOnShowListener(d->TvFocus.dialog(dialog));dialog.show();}
    int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}
